<?php
declare(strict_types=1);
require __DIR__.'/../../../app/bootstrap/bootstrap.php';require_once APP_PATH.'/helpers/mail_pilot.php';$mailOwner=mailCenterRequireOwner($pdo,$config);$draft=null;$outbox=null;$files=[];
try{
    $runtimeAccount=isset($_GET['outbox'])?mailCenterResourceAccount($pdo,$mailOwner,'outbox',mailCenterId($_GET['outbox'])):(isset($_GET['draft'])?mailCenterResourceAccount($pdo,$mailOwner,'draft',mailCenterId($_GET['draft'])):(isset($_GET['reply'])?mailCenterResourceAccount($pdo,$mailOwner,'message',mailCenterId($_GET['reply'])):mailCenterId($_GET['account']??null)));
    $runtime=mailPilotRuntime($pdo,$config,$mailOwner,$runtimeAccount);
    if(isset($_GET['outbox'])){$outbox=$runtime['send']->outbox(mailCenterId($_GET['outbox']));$account=$runtime['store']->account((int)$outbox['account_id'],false);}
    elseif(isset($_GET['draft'])){$draft=$runtime['send']->draft(mailCenterId($_GET['draft']));$account=$runtime['store']->account((int)$draft['account_id']);$data=$draft['content'];$data['reply_message_id']=$draft['reply_message_id'];$files=$runtime['attachments']->forDraft((int)$draft['id']);}
    elseif(isset($_GET['reply'])){$data=$runtime['send']->reply(mailCenterId($_GET['reply']));$account=$runtime['store']->account((int)$data['account_id']);}
    else{$account=$runtime['store']->account(mailCenterId($_GET['account']??null));$runtime['store']->connection((int)$account['id']);$data=['to'=>[],'cc'=>[],'bcc'=>[],'subject'=>'','body'=>'','reply_message_id'=>0];}
}catch(Throwable $error){mailPilotError($error,'/web/admin/central_contas/messages.php');}
$title='Escrever e-mail';$mailTab='messages';ob_start(); ?>
<div class="c-page mail-center"><div class="c-page-header"><h1 class="c-page-title"><?= $outbox?'Resultado do envio':'Escrever e-mail' ?></h1><a class="c-btn-secondary" href="messages.php?account=<?= (int)$account['id'] ?>">Voltar à caixa</a></div><?php require __DIR__.'/_nav.php'; ?>
<div class="mail-notice"><strong>Remetente: <?= mailCenterEscape($account['email']) ?></strong><p>Esta composição pertence exclusivamente a esta conta.</p></div>
<?php if($outbox): ?><section class="c-card"><h2><?= mailCenterEscape(mailPilotStatus($outbox['status'])) ?></h2><p>Aceitação e registro no Gmail não comprovam entrega ao destinatário.</p><?php if(in_array($outbox['status'],['unknown','accepted','sending'],true)): ?><p>Confira este envio antes de criar outra mensagem igual. A Central não o reenviará automaticamente.</p><form method="post" action="/app/actions/central_contas/send.php"><?= csrf_field() ?><input type="hidden" name="operation" value="reconcile"><input type="hidden" name="outbox_id" value="<?= (int)$outbox['id'] ?>"><button class="c-btn-secondary">Conferir no Gmail</button></form><?php endif; ?></section>
<?php elseif($draft&&$draft['status']!=='draft'): ?><div class="c-card"><p>Este rascunho já foi submetido. Consulte o resultado na caixa.</p></div>
<?php else: ?>
<form id="mail-compose" class="c-card mail-form" method="post" enctype="multipart/form-data" action="/app/actions/central_contas/draft_save.php">
<?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($draft['id']??0) ?>"><input type="hidden" name="revision" value="<?= (int)($draft['revision']??0) ?>"><input type="hidden" name="account_id" value="<?= (int)$account['id'] ?>"><input type="hidden" name="reply_message_id" value="<?= (int)($data['reply_message_id']??0) ?>">
<div class="mail-form-grid"><?php foreach(['to'=>'Para','cc'=>'Cc','bcc'=>'Cco']as$field=>$label): ?><label class="mail-form-full"><?= $label ?><input name="<?= $field ?>" maxlength="4096" value="<?= mailCenterEscape(implode(', ',$data[$field])) ?>" placeholder="Endereços separados por vírgula"></label><?php endforeach; ?>
<label class="mail-form-full">Assunto<input name="subject" maxlength="255" value="<?= mailCenterEscape($data['subject']) ?>" <?= !empty($data['reply_message_id'])?'readonly':'' ?>></label>
<label class="mail-form-full">Mensagem<textarea name="body" maxlength="65536" rows="12"><?= mailCenterEscape($data['body']) ?></textarea></label><label class="mail-form-full">Anexos<input type="file" name="attachments[]" multiple accept=".pdf,.jpg,.jpeg,.png,.webp,.txt,.csv"><small>Até 2 MB por arquivo e 6 MB no total. PDF, imagens e texto/CSV.</small></label></div>
<button class="c-btn" type="submit">Salvar rascunho e revisar</button></form>
<?php if($draft): ?><section class="c-card"><h2>Confirmar o conteúdo salvo</h2><dl><div><dt>De</dt><dd><?= mailCenterEscape($account['email']) ?></dd></div><div><dt>Para</dt><dd><?= mailCenterEscape(implode(', ',$data['to'])) ?></dd></div><div><dt>Cc</dt><dd><?= mailCenterEscape(implode(', ',$data['cc'])) ?></dd></div><div><dt>Cco</dt><dd><?= mailCenterEscape(implode(', ',$data['bcc'])) ?></dd></div><div><dt>Assunto</dt><dd><?= mailCenterEscape($data['subject']?:'(sem assunto)') ?></dd></div></dl><pre class="mail-body-text"><?= mailCenterEscape($data['body']) ?></pre>
<?php foreach($files as$file): ?><form method="post" action="/app/actions/central_contas/draft_attachment_remove.php" class="mail-actions"><?= csrf_field() ?><input type="hidden" name="attachment_id" value="<?= (int)$file['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$draft['revision'] ?>"><span>Anexo: <?= mailCenterEscape($file['filename']) ?> · <?= number_format((int)$file['byte_size']/1024,0,',','.') ?> KB</span><button class="c-btn-secondary">Remover anexo</button></form><?php endforeach; ?>
<form id="mail-confirm-send" method="post" action="/app/actions/central_contas/send.php"><?= csrf_field() ?><input type="hidden" name="draft_id" value="<?= (int)$draft['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$draft['revision'] ?>"><input type="hidden" name="submission_key" value="<?= mailCenterEscape($draft['submission_key']) ?>"><label class="mail-confirm"><input type="checkbox" name="confirmed" value="1" required>Confirmo o remetente e os destinatários do conteúdo salvo acima.</label><p id="mail-unsaved-warning" hidden>Salve as alterações antes de confirmar o envio.</p><button class="c-btn" type="submit">Enviar conteúdo salvo</button></form></section><?php endif; ?>
<?php endif; ?></div>
